      SUBROUTINE DECLSTC---- DECODE A BEAM LISTC-----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATUM.CIN'      INCLUDE 'FORDAT.CIN'      INCLUDE 'FORCNT.CIN'      INCLUDE 'IODATA.CIN'      INCLUDE 'IOFLAG.CIN'      INCLUDE 'LPDATA.CIN'      INCLUDE 'PARVAL.CIN'      INCLUDE 'RDBUFF.CIN'      INCLUDE 'RDCARD.CIN'      INCLUDE 'RDWRDS.CIN'C-----------------------------------------------------------------------      CHARACTER*15    KNAME      INTEGER         ICALL, ICALLO, IDIREP, INAMA, INAME, IREP      INTEGER         LAKE, LNAME      LOGICAL         FLAG      REAL            FAKE      EQUIVALENCE     (FAKE,LAKE)C-----------------------------------------------------------------------C      ERROR = .FALSE.CC---- INITIALIZEC      IUSED = 0      ICALL = 1      CALL RDNEXT      IF (ENDFIL) GO TO 700CC---- OPENING PARENTHESISC      CALL RDTEST('(',ERROR)      IF (ERROR) GO TO 800      CALL RDNEXT      IF (ENDFIL) GO TO 700CC---- PROCEDURE "DECODE LIST" ------------------------------------------C  100 IUSED = IUSED + 1      ILDAT(IUSED,2) = ICALLCC---- APPEND A NEW CALL CELLC  200 CONTINUECC---- REFLEXION?C      IF (ITEM .EQ. '-') THEN        CALL RDNEXT        IF (ENDFIL) GO TO 700        IDIREP = -1      ELSE        IDIREP = 1      ENDIFCC---- REPETITION?C      INDX = INDEX('0123456789',ITEM)      IF (INDX .NE. 0) THEN        CALL RDINT(IREP,FLAG)        IF (ENDFIL) GO TO 800        IF (FLAG) GO TO 600        CALL RDNEXT        IF (ENDFIL) GO TO 700        CALL RDTEST('*',FLAG)        IF (FLAG) GO TO 600        CALL RDNEXT        IF (ENDFIL) GO TO 700        IDIREP = IDIREP * IREP        NDESC = 1        LABLE = ' '        NWORD = 2        LAKE = 9        DATUM(1) = FAKE        LAKE = IREP        DATUM(2) = FAKE        CALL ELSTOR      ENDIFCC---- SUBLIST?C      IF (ITEM .EQ. '(') THEN        CALL RDNEXT        IF (ENDFIL) GO TO 700        ICALL = 2        ILDAT(IUSED+1,1) = IDIREP        GO TO 100      ENDIFCC---- DECODE IDENTIFIERC  300 CALL RDWORD(KNAME,LNAME)      IF (LNAME .EQ. 0) THEN        CALL RDFAIL        WRITE (IECHO,910)        GO TO 600      ELSE        CALL RDLOOK(KNAME,15,FNAME,1,NFORM,INAME)        IF (INAME .EQ. 0) THEN          IF (IDIREP .GT. 0) THEN            LAKE = 3            PDATA(1) = FAKE          ENDIF          IF (IDIREP .LT. 0) THEN            LAKE = 4            PDATA(1) = FAKE          ENDIF          CALL FNDDEF(KNAME,INAME)        ELSE          NDESC = 3          LABLE = KNAME          NWORD = 3          LAKE = 32          DATUM(1) = FAKE          LAKE = 3          DATUM(2) = FAKE          LAKE = INAME          DATUM(3) = FAKE          CALL ELSTOR        ENDIF        IF (IABS(IDIREP) .GT. 1) THEN          NDESC = 1          LABLE = ' '          NWORD = 2          LAKE = 9          DATUM(1) = FAKE          LAKE = 0          DATUM(2) = FAKE          CALL ELSTOR        ENDIF      ENDIFCC---- ACTUAL ARGUMENT LIST?C      CALL RDNEXT      IF (ENDFIL) GO TO 700      IF (ITEM .EQ. '(') THEN        INAMA = 1        NDESC = 3        LABLE = KNAME        NWORD = 3        LAKE = 32        DATUM(1) = FAKE        LAKE = 1         DATUM(2) = FAKE        LAKE = INAMA        DATUM(3) = FAKE        CALL ELSTOR        CALL RDNEXT        IF (ENDFIL) GO TO 700        ICALL = 3        GO TO 100      ENDIFCC---- COMMA OR RIGHT PARENTHESIS?C  500 CALL RDTEST(',)',FLAG)      IF (.NOT. FLAG) GO TO 700CC---- ERROR RECOVERYC  600 CALL RDFIND('(),;')      IF (ENDFIL) GO TO 800      ERROR = .TRUE.CC---- ANOTHER MEMBER?C  700 IF (ITEM .EQ. ',') THEN        IF (ICALL .EQ. 3) THEN          NDESC = 3          LABLE = KNAME          NWORD = 3          LAKE = 32          DATUM(1) = FAKE          LAKE = 2          DATUM(2) = FAKE          LAKE = INAMA          DATUM(3) = FAKE          CALL ELSTOR          INAMA = INAMA + 1          NDESC = 3          LABLE = KNAME          LAKE = 32          DATUM(1) = FAKE          LAKE = 1          DATUM(2) = FAKE          LAKE = INAMA          DATUM(3) = FAKE          CALL ELSTOR        ENDIF  710   CALL RDNEXT        IF (ENDFIL) GO TO 700        GO TO 200      ENDIFCC---- END OF LIST?C      IF (ITEM .EQ. ')') THEN        IREP  = ILDAT(IUSED,1)        ICALLO = ICALL        IUSED = IUSED - 1        IF (IUSED .GE. 1) ICALL = ILDAT(IUSED,2)        GO TO (800,720,730,500), ICALLO      ENDIF      GO TO 750CC---- CLOSE REPEAT FOR SUBLISTC  720 IF (IABS(IREP) .GE. 2) THEN        NDESC = 1        LABLE = ' '        NWORD = 2        LAKE = 9        DATUM(1) = FAKE        LAKE = 0        DATUM(2) = FAKE        CALL ELSTOR      ENDIF      CALL RDNEXT      IF (ENDFIL) GO TO 700      GO TO 500CC---- CLOSE DUMMY ARGUMENT SPECIFICATIONC  730 NDESC = 3      LABLE = KNAME      NWORD = 3      LAKE = 32      DATUM(1) = FAKE      LAKE = 2      DATUM(2) = FAKE      LAKE = INAMA      DATUM(3) = FAKE      CALL ELSTOR      CALL RDNEXT      IF (ENDFIL) GO TO 700      GO TO 500CC---- ANOTHER LIST WITHOUT A COMMA?C  750 IF (ITEM .EQ. '(') THEN        CALL RDNEXT        IF (ENDFIL) GO TO 700        ICALL = 4        GO TO 100      ENDIFCC---- END OF BEAM LINE LISTC  800 CONTINUE      RETURNC-----------------------------------------------------------------------  910 FORMAT(' *** ERROR *** BEAM LINE MEMBER MUST BE BEAM ELEMENT',     +       ' NAME, BEAM LINE NAME, OR LIST IN "()"'/' ')C-----------------------------------------------------------------------      END